function maximalSquare(matrix) {
  const m = matrix.length, n = matrix[0].length;
  let best = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      let k = 0;                                   // try sides 1, 2, ... with top-left (r, c)
      grow: while (r + k < m && c + k < n) {
        for (let i = 0; i <= k; i++) {             // check the new bottom row and right column
          if (matrix[r + k][c + i] !== "1" || matrix[r + i][c + k] !== "1") break grow;
        }
        k++;
      }
      best = Math.max(best, k);
    }
  }
  return best * best;
}

